const input = container.querySelector('[data-test="input"]');
expect(input, 'input present');
const inner = input.querySelector('input') || input;
inner.value = 'Ada';
inner.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
container.querySelector('[data-test="submit"]').click();
await tick();
await tick();
const greet = container.querySelector('[data-test="greeting"]');
expect(greet, 'greeting rendered after submit');
expect(greet.textContent.includes('Ada'), 'greeting mentions Ada: ' + greet.textContent);
